import type { PluginInput, PluginOptions } from "@opencode-ai/plugin"
import { randomUUID } from "node:crypto"

// Runtime v1.3.17 fields that the public SDK v1 does not yet describe.
export type Part = { type: string; [key: string]: unknown }
export type Message = { info: { id: string; sessionID: string; role: string; parentID?: string;
  time?: { created?: number; completed?: number }; finish?: string; summary?: unknown; error?: unknown; [key: string]: unknown }; parts: Part[] }
type Active = { ordinary: boolean; pending: Map<string, Set<unknown>> }
type Recovery = { pending: Set<string>; key: string; timer?: ReturnType<typeof setTimeout> }
const start = "<system-reminder>\nThe user sent the following message:\n"
const end = "\n\nPlease address this message and continue with your tasks.\n</system-reminder>"
const effective = (parts: Part[]) => parts.some(p => !p.ignored && !p.synthetic &&
  (p.type === "text" && typeof p.text === "string" && !!(p.text.startsWith(start) && p.text.endsWith(end)
    ? p.text.slice(start.length, -end.length) : p.text).trim() || p.type === "file" && typeof p.url === "string" && !!p.url.trim()))
const reminder = "[Steering reminder] Latest user guidance takes priority. Preserve completed results. Skip obsolete actions and report which actions were skipped and why. Re-read the original guidance before further tools."
const marker = "codeagentSteering"

export class SteeringState {
  private active = new Map<string, Active>()
  private compacting = new Set<string>()
  private recovering = new Map<string, Recovery>()
  private suppressions = new Set<string>()
  private input: PluginInput
  private options: PluginOptions
  constructor(input: PluginInput, options: PluginOptions) { this.input = input; this.options = options }
  private invalidate(id: string) {
    clearTimeout(this.recovering.get(id)?.timer)
    this.recovering.delete(id)
  }
  private clear(id: string) {
    this.active.delete(id); this.compacting.delete(id); this.invalidate(id)
  }
  private toast(message: string) {
    void this.input.client.tui.showToast({ body: { title: "Steering", message, variant: "info", duration: 2500 },
      signal: AbortSignal.timeout(1500) }).catch(() => undefined)
  }
  private params(id: string) {
    return { path: { id }, query: { directory: this.input.directory }, signal: AbortSignal.timeout(1500) }
  }
  async observe(id: string, output: { message: Message["info"]; parts: Part[] }) {
    const control = output.parts.find(p => p.synthetic &&
      (p.metadata as Record<string, { plugin?: string }> | undefined)?.[marker]?.plugin === "@oneshot/opencode-steering")
    if (control) return this.control(id, (control.metadata as Record<string, { recoveryKey?: string }>)[marker].recoveryKey)
    this.invalidate(id)
    const s = this.active.get(id)
    if (!s?.ordinary || output.message.role !== "user") return
    if (!effective(output.parts)) { s.pending.delete(output.message.id); return }
    s.pending.set(output.message.id, new Set(output.parts.filter(p => effective([p])).map(p => p.id)))
    this.toast("Guidance observed; waiting for next request")
  }
  async prepare(output: { messages: Message[] }) {
    const ids = new Set(output.messages.map(m => m.info.sessionID))
    if (ids.size !== 1 || ![...ids][0]) {
      for (const id of new Set([...this.active.keys(), ...this.compacting, ...this.recovering.keys()])) this.clear(id)
      return
    }
    const id = [...ids][0], previous = this.active.get(id)
    this.invalidate(id)
    const summary = this.compacting.delete(id)
    const included = !summary && output.messages.find(m => m.info.role === "user" && previous?.pending.has(m.info.id) && effective(m.parts))
    this.active.set(id, { ordinary: !summary, pending: new Map() })
    if (!included) return
    included.parts.push({ type: "text", synthetic: true, text: reminder })
    this.toast("Guidance absorbed at this request checkpoint")
  }
  async gate(input: { tool: string; sessionID: string; callID: string }) {
    if (input.tool === "steering_status" || input.callID?.startsWith("prt_")) return
    const s = this.active.get(input.sessionID)
    if (!s?.ordinary || !s.pending.size) return
    this.toast("Blocked an obsolete tool; latest guidance will be used next")
    throw new Error("STEERING_STALE_CONTEXT: guidance arrived after this request checkpoint. " + reminder)
  }
  compact(id: string) {
    this.clear(id); this.compacting.add(id)
  }
  private valid(id: string, r: Recovery) { return this.recovering.get(id) === r }
  private async recover(id: string, r: Recovery) {
    let dispatched = false
    try {
      const result = await this.input.client.session.messages(this.params(id))
      if (!this.valid(id, r) || result.error || !Array.isArray(result.data)) return
      const messages = result.data as unknown as Message[]
      if (messages.some(m => m.info.sessionID !== id)) return
      const assistant = [...messages].reverse().find(m => m.info.role === "assistant" && !m.info.summary)?.info
      const latest = [...messages].reverse().find(m => m.info.role === "user" && effective(m.parts))
      const parent = messages.findIndex(m => m.info.role === "user" && m.info.id === assistant?.parentID)
      if (!assistant || assistant.error || !assistant.time?.completed || !assistant.finish ||
        ["tool-calls", "unknown", "error"].includes(assistant.finish) && !assistant.structured ||
        !latest || !r.pending.has(latest.info.id) || parent < 0 || messages.indexOf(latest) <= parent) return
      const status = await this.input.client.session.status({ query: { directory: this.input.directory }, signal: AbortSignal.timeout(1500) })
      if (!this.valid(id, r) || status.error || !status.data || status.data[id]?.type && status.data[id].type !== "idle") return
      const session = await this.input.client.session.get(this.params(id))
      if (!this.valid(id, r) || session.error || !session.data || session.data.revert) return
      const { agent, model, system, variant, format } = latest.info
      const body = { agent, model, system, variant, format, parts: [{ type: "text", synthetic: true,
        text: "[Steering continuation] Re-read original saved guidance " + latest.info.id + ". " + reminder,
        metadata: { [marker]: { plugin: "@oneshot/opencode-steering", recoveryKey: r.key } } }] }
      const dispatch = await this.input.client.session.promptAsync({ ...this.params(id),
        body: body as NonNullable<Parameters<PluginInput["client"]["session"]["promptAsync"]>[0]>["body"] })
      dispatched = !dispatch.error
    } catch { if (this.valid(id, r)) this.invalidate(id) }
    finally { if (!dispatched && this.valid(id, r)) this.invalidate(id) }
  }
  private async control(id: string, key: unknown) {
    const r = this.recovering.get(id)
    let valid = !!r && r.key === key
    try {
      if (valid) {
        const session = await this.input.client.session.get(this.params(id))
        valid = this.valid(id, r!) && !session.error && !!session.data && !session.data.revert
        if (valid) {
          const status = await this.input.client.session.status({ query: { directory: this.input.directory }, signal: AbortSignal.timeout(1500) })
          valid = this.valid(id, r!) && !status.error && !!status.data && (!status.data[id] || status.data[id].type === "idle")
        }
      }
    } catch { valid = false }
    if (valid) { this.toast("Continuing with saved guidance"); return }
    if (r && r.key === key && this.valid(id, r)) this.invalidate(id)
    const token = randomUUID()
    this.suppressions.add(token)
    const timer = setTimeout(() => this.suppressions.delete(token), 30000); timer.unref?.()
    throw new Error(`STEERING_RECOVERY_SUPPRESSED (${token})`)
  }
  status(id: string) {
    const s = this.active.get(id)
    return { sessionID: id, request: s ? s.ordinary ? "ordinary" : "summary" : "unknown",
      pending: [...(s?.pending.keys() ?? [])], recovery: this.recovering.has(id), provider: "unknown", adopted: "unknown" }
  }
  async event(event: { type: string; properties?: unknown }) {
    const p = event.properties as { sessionID?: string; messageID?: string; info?: Message["info"] & { revert?: unknown };
      part?: Part & { sessionID?: string; messageID?: string }; status?: { type: string }; error?: { data?: { message?: string } } }
    const id = p?.sessionID ?? p?.part?.sessionID ?? p?.info?.sessionID ?? (event.type.startsWith("session.") ? p?.info?.id : undefined)
    if (!id) return
    if (event.type === "session.error") {
      const token = [...this.suppressions].find(t => p.error?.data?.message?.includes(t))
      if (token) { this.suppressions.delete(token); return }
    }
    if (event.type === "session.deleted" || event.type === "session.error" || p.info?.error ||
      event.type === "session.updated" && p.info?.revert) { this.clear(id); return }
    if (event.type === "message.removed" || event.type === "message.part.removed" ||
      event.type === "message.part.updated" && p.part && !effective([p.part]) &&
      this.active.get(id)?.pending.get(p.part.messageID ?? "")?.has(p.part.id)) {
      this.active.get(id)?.pending.delete(p.messageID ?? p.part?.messageID ?? "")
      this.invalidate(id)
    }
    if (event.type !== "session.status" || p.status?.type !== "idle") return
    const s = this.active.get(id)
    this.clear(id)
    if (!s?.ordinary || !s.pending.size || this.options.autoResume === false) return
    const r: Recovery = { pending: new Set(s.pending.keys()), key: randomUUID() }
    this.recovering.set(id, r)
    r.timer = setTimeout(() => this.invalidate(id), 5000); r.timer.unref?.()
    const timer = setTimeout(() => { if (this.valid(id, r)) void this.recover(id, r) }, 75); timer.unref?.()
  }
}
import type { Plugin } from "@opencode-ai/plugin"
import { z } from "zod"
import { SteeringState } from "./state.ts"

// The legacy loader calls every function export. Keep exactly one.
export const SteeringPlugin: Plugin = async (input, options = {}) => {
  const state = new SteeringState(input, options)
  return {
    tool: { steering_status: {
      description: "Read process-local request and pending guidance observations. Provider receipt and adoption remain unknown.",
      args: { messageID: z.string().optional() },
      async execute(_, context) { return JSON.stringify(state.status(context.sessionID), null, 2) },
    } },
    "chat.message": (input, output) => state.observe(input.sessionID, output),
    "experimental.chat.messages.transform": (_, output) => state.prepare(output),
    "experimental.session.compacting": async input => state.compact(input.sessionID),
    "tool.execute.before": input => state.gate(input),
    event: ({ event }) => state.event(event),
  }
}
// Real model evidence only. No scripted model decisions or fallback provider.
import assert from 'node:assert/strict'
import { execFileSync } from 'node:child_process'
import { mkdir, writeFile, readFile, access, rename } from 'node:fs/promises'
import path from 'node:path'
import { randomUUID } from 'node:crypto'
import { setTimeout as delay } from 'node:timers/promises'
import { createCodexCliBridge, invokeCodexCli } from './lib/codex-cli-bridge.mjs'
import { startKernel, until, entry, root } from '../external-plugins/steering/test/kernel.mjs'

const tui = process.argv.includes('--tui')
const natural = process.argv.includes('--natural')
if (natural && !tui) throw Error('--natural requires --tui')
const output = path.resolve((process.argv.includes('--out') ? process.argv[process.argv.indexOf('--out') + 1] : undefined) ?? path.join(root, '.codeagent/steering-v2-demo'))
// Every rerun starts with new files, retaining complete previous evidence.
if (await access(output).then(() => true, () => false)) await rename(output, output + '.archive-' + Date.now() + '-' + randomUUID().slice(0,8))
await mkdir(output, { recursive: true })
const cases = []
for (const enabled of [false, true]) {
  const out = path.join(output, enabled ? 'enabled' : 'disabled')
  await mkdir(out, { recursive: true })
  // Keep disposable XDG caches/databases locally; export messages and logs below.
  await writeFile(path.join(out, '.gitignore'), 'kernel/\n')
  const requests = [], results = []
  const item = { enabled, source: 'real', tui, natural, timing: natural ? 'unheld-tool-running' : 'held-model-decision', passed: false, out }; cases.push(item)
  let kernel, bridge, release, held = false, socket, session
  const exists = name => access(path.join(out, name)).then(() => true, () => false)
  const capture = async name => {
    if (!socket) return
    const text = execFileSync('tmux', ['-L', socket, 'capture-pane', '-p', '-S', '-2000', '-t', 'demo'], { encoding: 'utf8' })
    await writeFile(path.join(out, name + '.txt'), text)
  }
  try {
    const tool = path.join(out, 'action.mjs')
    const zod = path.join(root, 'node_modules/zod/index.js')
    await writeFile(tool, `import {z} from ${JSON.stringify(zod)}; import {writeFile} from 'node:fs/promises'; import path from 'node:path'; import {setTimeout as delay} from 'node:timers/promises';
      export default async () => ({tool:{work_action:{description:'Write one task artifact. Use once for each requested step. ${natural ? 'Each action sleeps 8 seconds before writing.' : ''}',
      args:{name:z.enum(['checkpoint.md','obsolete.md','SUMMARY.md']),content:z.string()},
      async execute(args){if (${natural}) await delay(8000); await writeFile(path.join(${JSON.stringify(out)},args.name),args.content);return 'Wrote '+args.name}}}})`)
    bridge = await createCodexCliBridge({ codexBinary: process.env.CODEX_BINARY ?? 'codex', backend: async (body, options) => {
      const n = requests.length; requests.push(body)
      await writeFile(path.join(out, `request-${n}.json`), JSON.stringify(body, null, 2))
      const result = await invokeCodexCli(body, { ...options, timeoutMs: 120000, onEvidence: async evidence => {
        await writeFile(path.join(out, `codex-${n}.jsonl`), evidence.jsonl)
        await writeFile(path.join(out, `response-${n}.json`), JSON.stringify({ decision: evidence.decision, usage: evidence.usage }, null, 2))
      } })
      results.push(result)
      // Hold the model's own obsolete decision after it has chosen it, before
      // forwarding the unchanged decision to OpenCode's normal tool checkpoint.
      if (!natural && !held && await exists('checkpoint.md') && result.decision.kind === 'tool') {
        assert.equal(result.decision.tool_name, 'work_action')
        assert.equal(JSON.parse(result.decision.arguments).name, 'obsolete.md', 'Real model must choose the second original step')
        held = true
        await new Promise(resolve => { release = resolve })
      }
      return result
    } })
    kernel = await startKernel({ directory: out, out: path.join(out, 'kernel'), plugin: [tool, ...(enabled ? [entry] : [])],
      extra: { provider: { real: { npm: '@ai-sdk/openai-compatible', options: { apiKey: bridge.apiKey, baseURL: bridge.baseURL },
        models: { [bridge.modelID]: { name: 'Real Codex CLI', tool_call: true, limit: { context: 128000, output: 8000 } } } } },
        model: 'real/' + bridge.modelID, agent: { title: { disable: true }, summary: { disable: true }, build: { tools: { '*': false, work_action: true } } } } })
    session = await kernel.request('/session', { title: 'Real steering ' + enabled, permission: [{ permission: '*', pattern: '*', action: 'allow' }] })
    const route = '/session/' + session.id
    const task = (natural ? 'Each action must sleep 8 seconds before writing; work_action implements that delay. ' : '') + 'Use work_action to perform these separate steps in order, exactly one artifact per tool call: (1) write checkpoint.md with "completed first step"; (2) write obsolete.md with "original second step"; (3) write SUMMARY.md summarizing what you completed. Then give a brief final answer.'
    const guidance = 'Change direction now: keep checkpoint.md. Skip the pending obsolete.md action. Write SUMMARY.md explaining that obsolete.md was skipped because of this latest guidance, and retain the completed first step. Do not perform obsolete actions.'
    const sendKeys = text => execFileSync('tmux', ['-L', socket, 'send-keys', '-t', 'demo', '-l', text])
    if (tui) {
      socket = 'steering-v2-' + randomUUID().slice(0, 12)
      const binary = process.env.OPENCODE_BINARY ?? path.join(process.env.HOME, '.local/opencode-1.3.17/opencode')
      const launcher = path.join(out, 'launch.sh')
      const quote = s => "'" + s.replaceAll("'", "'\\''") + "'"
      await writeFile(launcher, '#!/bin/sh\n' + Object.entries(kernel.env).filter(([k]) => k.startsWith('XDG_') || k.startsWith('OPENCODE_')).map(([k, v]) => 'export ' + k + '=' + quote(v)).join('\n') + '\nexec ' + [binary, 'attach', kernel.url, '--dir', out, '--session', session.id].map(quote).join(' ') + '\n', { mode: 0o700 })
      execFileSync('tmux', ['-L', socket, 'new-session', '-d', '-s', 'demo', '-x', '140', '-y', '45', launcher])
      await until(() => execFileSync('tmux', ['-L', socket, 'capture-pane', '-p', '-t', 'demo'], { encoding: 'utf8' }).includes('Real Codex CLI'), 'TUI ready', 30000)
      sendKeys(task); execFileSync('tmux', ['-L', socket, 'send-keys', '-t', 'demo', 'Enter'])
    } else await kernel.request(route + '/prompt_async', { model: { providerID: 'real', modelID: bridge.modelID }, agent: 'build', parts: [{ type: 'text', text: task }] })
    if (natural) await until(async () => (await kernel.request(route + '/message')).some(m => m.parts.some(p => p.type === 'tool' && p.tool === 'work_action' && p.state.status === 'running' && p.state.input?.name === 'checkpoint.md')), 'first sleep 8 tool running', 180000)
    else await until(() => release, 'real model stale decision barrier', 180000)
    await capture('before-guidance')
    if (tui) { sendKeys(guidance); execFileSync('tmux', ['-L', socket, 'send-keys', '-t', 'demo', 'Enter']) }
    else await kernel.request(route + '/prompt_async', { model: { providerID: 'real', modelID: bridge.modelID }, agent: 'build', parts: [{ type: 'text', text: guidance }] })
    await until(async () => (await kernel.request(route + '/message')).some(m => m.parts.some(p => p.text === guidance)), 'native guidance saved', 30000)
    await capture('guidance-submitted'); release?.(); release = undefined
    await until(async () => await exists('SUMMARY.md') && !(await kernel.request('/session/status'))[session.id], 'real final summary and idle', 240000)
    await capture('completed')
    const messages = await kernel.request(route + '/message')
    await writeFile(path.join(out, 'messages.json'), JSON.stringify(messages, null, 2))
    if (!natural) assert.equal(await exists('obsolete.md'), !enabled)
    if (natural && enabled) assert.equal(await exists('obsolete.md'), false)
    item.obsoleteWritten = await exists('obsolete.md')
    assert.equal(await readFile(path.join(out, 'checkpoint.md'), 'utf8'), 'completed first step')
    const summary = await readFile(path.join(out, 'SUMMARY.md'), 'utf8')
    assert.ok(summary.length > 0)
    if (enabled) {
      assert.ok(/skip|跳过/i.test(summary), 'Real model must explain skipped action')
      if (!natural) assert.ok(messages.flatMap(m => m.parts).some(p => p.type === 'tool' && p.state.status === 'error' && p.state.error.includes('STEERING_STALE_CONTEXT')))
    }
    item.summary = summary; item.requests = requests.length; item.usage = bridge.stats.usage; item.passed = true
  } catch (e) { item.error = e.stack; await capture('failure').catch(() => {}) }
  finally {
    release?.()
    if (socket) { try { execFileSync('tmux', ['-L', socket, 'kill-server']) } catch {} }
    if (kernel) {
      if (!item.passed && session) await writeFile(path.join(out, 'messages.json'), JSON.stringify(await kernel.request('/session/' + session.id + '/message').catch(() => []), null, 2))
      await kernel.stop()
      await writeFile(path.join(out, 'kernel-log.txt'), await readFile(path.join(out, 'kernel/kernel.log'), 'utf8'))
    }
    if (bridge) await bridge.close()
    await writeFile(path.join(out, 'report.json'), JSON.stringify(item, null, 2))
  }
}
const report = { source: 'real', tui, natural, cases, passed: cases.every(c => c.passed) }
if (natural) report.observation = cases.every(c => c.passed && !c.obsoleteWritten) ? 'Both controls naturally adopted guidance; no differential steering claim.' : 'See per-case artifacts for observed natural timing.'
await writeFile(path.join(output, 'report.json'), JSON.stringify(report, null, 2))
console.log(JSON.stringify(report, null, 2))
if (!report.passed) process.exitCode = 1

import assert from 'node:assert/strict'
import { test } from 'node:test'
import { SteeringPlugin } from '../src/index.ts'
import { composeSteeringHooks } from '../../src/steering/compose.ts'
import { setTimeout as delay } from 'node:timers/promises'

async function fixture(options = {}, plugin = SteeringPlugin) {
  const sessions = {}, reads = [], controls = [], statuses = {}, details = {}, sdk = []
  let hooks, offline = false
  const client = { tui: { showToast: async () => { throw Error('toast offline') } }, session: {
    messages: async ({ path }) => { sdk.push('messages'); reads.push(path.id); if (offline) throw Error('offline'); return { data: structuredClone(sessions[path.id] ?? []) } },
    status: async () => { sdk.push('status'); return { data: statuses } },
    get: async ({ path }) => { sdk.push('get'); return { data: details[path.id] ?? { id: path.id } } },
    promptAsync: async args => { sdk.push('promptAsync'); controls.push(args); return { data: undefined } },
  } }
  hooks = await plugin({ directory: '/fixture', client }, options)
  const event = (type, properties) => hooks.event({ event: { type, properties } })
  const user = (id, text = 'task', extra = [], sessionID = 'one') => ({ info: { id, sessionID, role: 'user', agent: 'build',
    model: { providerID: 'fixture', modelID: 'fixture' }, time: { created: 1 } },
    parts: [{ id: 'p_' + id, type: 'text', text, sessionID, messageID: id }, ...extra.map((p, i) => ({ id: 'extra_' + i, messageID: id, sessionID, ...p }))] })
  const observe = m => hooks['chat.message']({ sessionID: m.info.sessionID }, { message: m.info, parts: m.parts })
  const persist = async m => {
    const list = sessions[m.info.sessionID] ??= []
    const index = list.findIndex(v => v.info.id === m.info.id)
    if (index < 0) list.push(m); else list[index] = m
    await event('message.updated', { info: m.info })
    for (const part of m.parts) await event('message.part.updated', { part })
    return m
  }
  const save = async m => { await observe(m); return persist(m) }
  const assistant = (id, parentID, sessionID = 'one') => {
    const m = { info: { id, parentID, sessionID, role: 'assistant', time: { created: 2 } }, parts: [] }
    ;(sessions[sessionID] ??= []).push(m); return m
  }
  const prepare = async (m, context) => {
    const output = { messages: structuredClone(context ?? sessions[m.info.sessionID].filter(v => v !== m)) }
    await hooks['experimental.chat.messages.transform']({}, output); return output.messages
  }
  const call = async (m, callID, tool = 'bash', notify = true) => {
    const part = { id: 'part_' + callID, callID, type: 'tool', tool, messageID: m.info.id, sessionID: m.info.sessionID }
    m.parts.push(part)
    if (notify) await event('message.part.updated', { part })
    return hooks['tool.execute.before']({ tool, sessionID: m.info.sessionID, callID }, { args: {} })
  }
  const status = async (id = 'one') => JSON.parse(await hooks.tool.steering_status.execute({}, { sessionID: id }))
  return { sessions, reads, controls, client, statuses, details, sdk, hooks, event, user, observe, persist, save, assistant, prepare, call, status,
    offline: () => { offline = true } }
}
async function running(options, plugin) {
  const f = await fixture(options, plugin)
  const task = await f.save(f.user('m01'))
  const a = f.assistant('m03', task.info.id)
  await f.prepare(a, [task])
  return { ...f, task, a }
}
async function until(fn) { const end = Date.now() + 2000; while (Date.now() < end) { if (await fn()) return; await delay(10) } assert.fail('timeout') }
async function finish(f) { f.a.info.finish = 'stop'; f.a.info.time.completed = 3; await f.event('session.status', { sessionID: 'one', status: { type: 'idle' } }) }

test('A1/A5 idle input >300 and 129 cancelled sessions never create retained state or SDK reads', async () => {
  const f = await fixture()
  for (let i = 0; i < 350; i++) {
